var slide_commentary_user_default = "\uB2E4\uC74C\uC740 \uAC15\uC758 \uC2AC\uB77C\uC774\uB4DC {{slideNum}}/{{totalSlides}}\uC758 \uC774\uBBF8\uC9C0\uC785\uB2C8\uB2E4. \uC9C0\uC2DC\uB41C \uB0B4\uC6A9\uACFC \uBB38\uCCB4 \uADDC\uCE59\uB300\uB85C \uC774 \uC2AC\uB77C\uC774\uB4DC\uC758 \uD55C\uAD6D\uC5B4 \uB9C8\uD06C\uB2E4\uC6B4 \uD574\uC124\uC744 \uC791\uC131\uD558\uC2DC\uC624.\n\n- \uCD9C\uB825\uC740 \uD574\uC124 \uBCF8\uBB38\uB9CC \uC501\uB2C8\uB2E4.\n- \uBD84\uB7C9\uC740 200~500\uC790\uC785\uB2C8\uB2E4. \uD45C\uC9C0, \uBAA9\uCC28, \uB9C8\uBB34\uB9AC \uC2AC\uB77C\uC774\uB4DC\uB294 \uB2E4\uB8F0 \uC8FC\uC81C\uB098 \uC81C\uBAA9\uB9CC \uD55C \uC904\uB85C \uC501\uB2C8\uB2E4.{{conceptList}}{{transcriptBlock}}\n";

// src/prompts/slidePrompt.ts
